KV_='import os\nLOG = "data.log"\nindex = {}                      # 键 → 文件中的字节偏移量\n\ndef put(k, v):\n    with open(LOG, "ab") as f:\n        index[k] = f.tell()\n        f.write(f"{k},{v}\\n".encode())\n\ndef get(k):\n    if k not in index: return None\n    with open(LOG, "rb") as f:\n        f.seek(index[k])\n        return f.readline().decode().rstrip("\\n").split(",", 1)[1]\n\ndef compact():\n    global index\n    live = {k: get(k) for k in index}\n    os.remove(LOG); index = {}\n    for k, v in live.items(): put(k, v)\n\nif os.path.exists(LOG): os.remove(LOG)\nfor i in range(1000):\n    put(f"user{i % 10}", f"visits={i}")\nprint("get user3 =", get("user3"))\nprint("日志大小", os.path.getsize(LOG), "字节，键数", len(index))\ncompact()\nprint("压缩后", os.path.getsize(LOG), "字节；get user3 =", get("user3"))'
MG_='import heapq\n# 三个 SSTable：每个都按键排序；编号越大越新\nseg1 = [("apple", 1), ("cat", 1), ("dog", 1)]\nseg2 = [("apple", 2), ("bird", 2), ("dog", None)]      # None 表示删除（墓碑）\nseg3 = [("cat", 3), ("eel", 3)]\nmerged = {}\nfor k, v, age in heapq.merge(*[[(k, v, -i) for k, v in s] for i, s in enumerate([seg1, seg2, seg3])], key=lambda t: (t[0], t[2])):\n    if k not in merged: merged[k] = v                  # 同一个键只保留最新的\nout = [(k, v) for k, v in merged.items() if v is not None]\nprint(out)'
TITLE='存储引擎：日志结构与 LSM 树';DESC='第 4 章的第一部分。数据库最朴素的实现是一个只追加的文件——写入极快，读取却要扫描全部。本课从这里出发：加上内存中的哈希索引（Bitcask 模式）、分段与压缩合并，再把段文件改成按键排序的 SSTable，得到 LSM 树：内存表、刷盘、多层合并、布隆过滤器，以及分层合并与大小分级合并两种策略的取舍。练习里你会写出一个 30 行的日志结构键值存储。';NEXT='B 树、二级索引与内存数据库'
MIN=60
SUM=['<b>只追加的日志</b>：写入就是在文件末尾追加一行，顺序写非常快；读取要从头扫描，O(n)。<b>索引</b>是从主数据派生出来的额外结构，用来加速读取——但每个索引都会拖慢写入，所以数据库不会默认索引一切。',
'<b>哈希索引</b>：在内存里保存“键 → 文件偏移量”的哈希表，读取一次寻址即可（Bitcask 的做法）。前提是所有键都放得进内存；不支持范围查询。为了不让日志无限增长，把日志切成<b>段</b>，对旧段做<b>压缩</b>（只保留每个键的最新值）并合并；删除用一条特殊的<b>墓碑</b>记录表示。崩溃恢复要重建哈希表（可以保存快照加速）。',
'<b>SSTable</b>（排序字符串表）：段内的键按顺序排列。好处：合并多个段就像归并排序，简单高效；不需要把所有键放进内存，稀疏索引（每隔几 KB 记一个键）就够了，块还可以压缩；天然支持范围查询。',
'<b>LSM 树</b>的写路径：写入先进<b>内存表</b>（memtable，有序结构如跳表），同时追加到预写日志（WAL）以防崩溃；内存表达到阈值后作为新的 SSTable 写到磁盘。读路径：依次查内存表、最新的段、较旧的段……为了避免为不存在的键读遍所有段，每个 SSTable 带一个<b>布隆过滤器</b>，能确定地回答“不在这里”。后台不断合并段，丢弃不再需要的旧值；墓碑只有在确认不会让更旧值复活、且没有快照仍需旧版本时才能清理。RocksDB、Cassandra、ScyllaDB、HBase 都是 LSM 结构。',
'<b>合并策略</b>：<b>大小分级</b>（size-tiered）把大小相近的段合并成更大的段，写放大小，但空间占用和读放大较大；<b>分层</b>（leveled）把键范围切成小文件分到多层，每层大小递增，读和空间更省，写放大更大。写放大还会消耗 SSD 寿命。',
'同样的思想在你学过的系统里随处可见：Redis 的 AOF 只追加并定期重写（<a href="../redis/index.html">Redis 课程</a>），Kafka 的分区就是分段的追加日志，日志压缩只保留每个键的最新值（<a href="../kafka/l12.html">Kafka 第 12 课</a>）。']
